  /* ô nút giao Bạch Đằng – nhánh rẽ Cầu Rồng: dải giữa mở và có mặt đường ở tim */
  const j = pads.find((p) => p.id === 'jct.bachDang.dragon.S');
  const ys = roadTris.map((t) => yAt(t, -R.riverX, (j.z0 + j.z1) / 2)).filter((y) => !Number.isNaN(y));
