30	export interface DrRect { x0: number; x1: number; z0: number; z1: number }
31	interface DrRaised extends DrRect { top: (x: number) => number }       // dải nổi cũ: mặt trên theo x
32	interface DrPiece extends DrRect { y: number; full: boolean; alongX: boolean }   // mảnh mặt đường cần dựng
