37	const PLATE = 0.01;                                                 // m — tấm phủ cao hơn mặt trên dải nổi cũ (spec §4.3)
38	const PLAIN_V = 0.3;                                                // v texture road2 ở vùng nhựa trơn (vạch mép 0,06 / 0,94, vạch giữa 0,5)
