40	const LIN = R.median / 2, LOUT = LIN + R.half;                      // 1,5 / 10,5
41	const AX0 = R.axisX0, AX1 = R.axisX1;
42	const RIVER = { W: [-2600, 2600], E: [-2300, 2600] };               // m — z hai đường ven sông trong streets.ts:25
43	const SITE = { W: -3250 + 40, E: -3700 + 40 };                      // m — đầu Bắc mặt đường nối dài trong site.ts:16,32
44	
45	/* hai dải đối xứng quanh tim c theo trục ngang (along x) hoặc dọc (along z), mép trong a, mép ngoài b */
46	const bandX = (x0: number, x1: number, c: number, a: number, b: number): DrRect[] => [{ x0, x1, z0: c - b, z1: c - a }, { x0, x1, z0: c + a, z1: c + b }];
47	const bandZ = (c: number, a: number, b: number, z0: number, z1: number): DrRect[] => [{ x0: c - b, x1: c - a, z0, z1 }, { x0: c + a, x1: c + b, z0, z1 }];
48	
49	/* ===== Mặt đường đã có (bằng mặt đất, phần cầu / hầm không cần vì ô 'bridge' / 'tunnel' không dựng) ===== */
50	function drOld(): DrRect[] {
51	  const out: DrRect[] = [];
52	  const DR_X = CONFIG.length / 2, DR_IN = CONFIG.median / 2, DR_OUT = DR_IN + CONFIG.lanesPerDir * CONFIG.laneWidth + CONFIG.shoulder;
53	  for (const [a, b] of [[AX0, -DR_X], [DR_X, AX1]]) out.push(...bandX(a, b, 0, DR_IN, DR_OUT));
54	  for (const [a, b] of [[AX0, -SH.fixedStart], [SH.fixedStart, AX1]]) out.push(...bandX(a, b, SH.z, SH.median / 2, SH.median / 2 + SH.laneWidth));
55	  out.push(...bandX(AX0, AX1, TTL.z, TTL.median / 2, TTL.median / 2 + TTL.lanesPerDir * TTL.laneWidth));
56	  const hrW = HR.shoulder * 2 + HR.laneWidth * HR.lanesPerDir;
57	  for (const [a, b] of [[AX0, -HR.coverHalf], [HR.coverHalf, AX1]]) out.push(...bandX(a, b, HR.z, HR.tubeCenter - hrW / 2, HR.tubeCenter + hrW / 2));
58	  out.push(...bandX(R.tpX0, AX1, TP.z, TP.median / 2, TP.median / 2 + 2 * TP.laneWidth));
59	  out.push(...bandZ(-R.riverX, LIN, LOUT, SITE.W, RIVER.W[1]), ...bandZ(R.riverX, LIN, LOUT, SITE.E, RIVER.E[1]));
60	  return out;
61	}
62	/* ===== Dải giữa / vỉa hè cũ của các cầu: không cắt, phủ tấm ===== */
63	function drRaised(): DrRaised[] {
64	  const out: DrRaised[] = [];
65	  const add = (x0: number, x1: number, z0: number, z1: number, top: (x: number) => number) => out.push({ x0, x1, z0, z1, top });
66	  const flat = (h: number) => () => ROAD + h;
67	  for (const [a, b] of [[AX0, -SH.fixedStart], [SH.fixedStart, AX1]]) add(a, b, SH.z - SH.median / 2, SH.z + SH.median / 2, (x) => shRoadY(x) + 0.3);
68	  const ttlW = TTL.roadProfile[1][0], ttlE = TTL.roadProfile[TTL.roadProfile.length - 2][0];   // −470 / 450 (deck.ts xr0 / xr1)
69	  for (const [a, b] of [[AX0, ttlW], [ttlE, AX1]]) add(a, b, TTL.z - TTL.median / 2, TTL.z + TTL.median / 2, flat(0.3));
70	  for (const [a, b] of [[AX0, -HR.rampHalf], [HR.rampHalf, AX1]]) {
71	    add(a, b, HR.z - HR.tubeNear, HR.z + HR.tubeNear, (x) => hrRoadY(x) + 0.3);
72	    for (const s of [-1, 1]) { const c = HR.z + s * (HR.tubeFar + 1.5); add(a, b, c - 1.5, c + 1.5, (x) => hrRoadY(x) + 0.2); }
73	  }
74	  const tpEnd = TP.endX + TP.embankment;
75	  for (const [a, b] of [[R.tpX0, -tpEnd], [tpEnd, AX1]]) add(a, b, TP.z - TP.median / 2, TP.z + TP.median / 2, flat(0.3));
76	  return out;
77	}
78	
79	/* ===== Trừ hình chữ nhật: alongX = cắt các lát theo x trước (giữ đủ bề ngang z cho ô chạy dọc X) ===== */
80	function drSub(a: DrRect, b: DrRect, alongX: boolean): DrRect[] {
81	  const ix0 = Math.max(a.x0, b.x0), ix1 = Math.min(a.x1, b.x1), iz0 = Math.max(a.z0, b.z0), iz1 = Math.min(a.z1, b.z1);
82	  if (ix1 - ix0 <= EPS || iz1 - iz0 <= EPS) return [a];
83	  const out: DrRect[] = [];
84	  if (alongX) {
85	    out.push({ x0: a.x0, x1: ix0, z0: a.z0, z1: a.z1 }, { x0: ix1, x1: a.x1, z0: a.z0, z1: a.z1 });
86	    out.push({ x0: ix0, x1: ix1, z0: a.z0, z1: iz0 }, { x0: ix0, x1: ix1, z0: iz1, z1: a.z1 });
87	  } else {
88	    out.push({ x0: a.x0, x1: a.x1, z0: a.z0, z1: iz0 }, { x0: a.x0, x1: a.x1, z0: iz1, z1: a.z1 });
89	    out.push({ x0: a.x0, x1: ix0, z0: iz0, z1: iz1 }, { x0: ix1, x1: a.x1, z0: iz0, z1: iz1 });
90	  }
91	  return out.filter((r) => r.x1 - r.x0 > MIN && r.z1 - r.z0 > MIN);
92	}
93	const drSubAll = (a: DrRect, bs: DrRect[], alongX: boolean) => bs.reduce((acc, b) => acc.flatMap((r) => drSub(r, b, alongX)), [a]);
94	const drOverlap = (a: DrRect, b: DrRect) => Math.min(a.x1, b.x1) - Math.max(a.x0, b.x0) > EPS && Math.min(a.z1, b.z1) - Math.max(a.z0, b.z0) > EPS;
95	
96	/* ===== Mảnh mới và tấm phủ (tính một lần: dữ liệu thuần, không ngẫu nhiên) ===== */
97	let cache: { pieces: DrPiece[]; plates: DrPiece[]; medians: DrRect[]; open: DrPad[] } | null = null;
98	function drPlan() {
99	  if (cache) return cache;
100	  const open = drBuildPads().filter((p) => p.kind === 'road' || p.kind === 'slip' || p.kind === 'junction');
101	  const old = drOld(), raised = drRaised(), covered = [...old, ...raised];
102	  /* mặt đường nối dài trong site.ts thấp hơn roadY 0,08 m: mảnh lấp chỗ dải giữa của nó dùng cùng cao độ */
103	  const yOf = (r: DrRect) => {
104	    const cx = (r.x0 + r.x1) / 2, cz = (r.z0 + r.z1) / 2;
105	    return Math.abs(Math.abs(cx) - R.riverX) <= LOUT && cz < (cx < 0 ? RIVER.W[0] : RIVER.E[0]) ? LAND + LIFT : ROAD + LIFT;
106	  };
107	  const pieces: DrPiece[] = [], plates: DrPiece[] = [], medians: DrRect[] = [];
108	  for (const p of open) {
109	    const alongX = p.x1 - p.x0 >= p.z1 - p.z0, lane = p.kind !== 'junction';
110	    for (const r of drSubAll(p, covered, alongX)) {
111	      const full = lane && (alongX ? Math.abs(r.z0 - p.z0) < MIN && Math.abs(r.z1 - p.z1) < MIN : Math.abs(r.x0 - p.x0) < MIN && Math.abs(r.x1 - p.x1) < MIN);
112	      pieces.push({ ...r, y: yOf(r), full, alongX });
113	    }
114	    for (const q of raised) {
115	      if (!drOverlap(p, q)) continue;
116	      const r = { x0: Math.max(p.x0, q.x0), x1: Math.min(p.x1, q.x1), z0: Math.max(p.z0, q.z0), z1: Math.min(p.z1, q.z1) };
117	      plates.push({ ...r, y: Math.max(q.top(r.x0), q.top(r.x1)) + PLATE, full: false, alongX });
118	    }
119	    /* dải giữa đường mới: giữa cặp ô hai chiều (.W/.E hoặc .N/.S) không chồng mặt đường cũ nào */
120	    const m = /^(.*)\.(W|N)$/.exec(p.id);
121	    if (p.kind === 'road' && m && !old.some((o) => drOverlap(o, p))) {
