  const open = pads.filter((p) => p.kind !== 'bridge' && p.kind !== 'tunnel');
  const E = 1e-3, bad: string[] = [];
  for (const g of [...geos.roads2, ...geos.medians]) {
    const pos = g.attributes.position;
    for (let i = 0; i < pos.count; i++) {
