      for (const p of open) if (x > p.x0 + E && x < p.x1 - E && z > p.z0 + E && z < p.z1 - E && y > p.y(x, z) + 0.02 + 1e-4) bad.push(`${p.id} (${x}, ${y}, ${z}) > ${p.y(x, z)}`);
