    ['ttl', -1900, -470, TTL.z, TTL.median / 2], ['ttl', 450, 1480, TTL.z, TTL.median / 2],
    ['thuanPhuoc', -1500, -tpE, TP.z, TP.median / 2], ['thuanPhuoc', tpE, 1480, TP.z, TP.median / 2]
  ];
