// So sánh draw call (renderer.info.render.calls, gồm cả bóng đổ, phản chiếu nước và bloom)
// giữa bản gốc (một file HTML) và bản build Vite, ở mọi góc nhìn, ban ngày và ban đêm.
//
//   npm run build && node tests/drawcalls.mjs [thư-mục-bản-gốc]
//
// Thư mục bản gốc (tùy chọn) phải chứa index.html có móc ?test (window.__app) và thư mục three/.
import { fileURLToPath } from 'node:url';
import { serveDir, launch, openApp, frames, pickView } from './lib.mjs';

const VIEWS = [
  ['dragon', 'overview'], ['dragon', 'head'], ['dragon', 'tail'], ['dragon', 'drive'], ['dragon', 'bird'], ['dragon', 'walk'],
  ['tp', 'tpBay'], ['tp', 'tpWater'], ['tp', 'tpDrive'], ['tp', 'tpBoth'],
  ['ttl', 'ttlOverview'], ['ttl', 'ttlBase'], ['ttl', 'ttlDeck'], ['ttl', 'ttlBoth'],
  ['sh', 'shOverview'], ['sh', 'shTop'], ['sh', 'shBank'], ['sh', 'shDeck'],
  // Hầm vượt sông Hàn (bản gốc không có: tự bỏ qua nếu thiếu nút)
  ['hr', 'hrOverview'], ['hr', 'hrCutaway'], ['hr', 'hrPortalW'], ['hr', 'hrPortalE'], ['hr', 'hrDrive'], ['hr', 'hrGallery'],
  // Hai bờ sông Hàn
  ['dragon', 'rfHearts'], ['dragon', 'rfBank'],
  // Thời tiết (GĐ6; bản gốc không có: tự bỏ qua nếu thiếu nút)
  ['tp', 'wxRiverMouth'], ['ttl', 'wxTtlStays'], ['dragon', 'wxStreet'],
  // Vòng quay Mặt Trời (GĐ3; bản gốc không có: tự bỏ qua nếu thiếu nút)
  ['sw', 'swOverview'], ['sw', 'swFront'], ['sw', 'swBase'], ['sw', 'swFromTTL'], ['sw', 'swNight'], ['sw', 'swTop'],
  // Ngồi cabin (GĐ5): camera gắn cabin, không thêm mesh
  ['sw', 'swRide'],
  // Tour Vòng quay (GĐ7): đo lúc Tour đang ở điểm 5 (trong cabin ở đỉnh, camera do cabin đặt), cùng ngân sách swRide
  ['sw', 'swTour']
];

async function setNight(page, v) {
  await page.evaluate((v) => { window.__app.dayNight.target = v; window.__app.dayNight.night = v; }, v);
  await page.waitForFunction((v) => Math.abs(window.__app.dayNight.night - v) < 1e-6, v, { timeout: 60000 });
  await frames(page, 3);
}

/** Trung vị của vài khung hình (xe cộ, thuyền chạy nên số có thể dao động nhẹ). */
async function sample(page) {
  const xs = [];
  for (let i = 0; i < 5; i++) { await frames(page, 1); xs.push(await page.evaluate(() => window.__app.renderer.info.render.calls)); }
  xs.sort((a, b) => a - b);
  return xs[2];
}

async function measure(browser, url) {
  const { page, errors } = await openApp(browser, url);
  const out = {};
  for (const night of [0, 1]) {
    await setNight(page, night);
    for (const [bridge, view] of VIEWS) {
      if (!(await page.$(`button[data-view="${view}"]`))) continue;
      await pickView(page, bridge, view);
      if (view === 'swNight') await setNight(page, night);   // góc này tự chuyển sang đêm khi bấm: trả về ngày/đêm đang đo (rfHearts giữ nguyên cách đo cũ để khớp bảng chuẩn)
      if (view === 'swRide') await page.evaluate(() => { window.__app.swRide.blend = 1; });   // bỏ chặng bay vào cabin: đo khi camera đã ở trong cabin
      if (view === 'swTour') await page.evaluate(() => { const d = window.__app.tours.sw.durs; window.__app.tour.t = d.slice(0, 3).reduce((a, x) => a + x, 0) + 0.6 * d[3]; window.__app.swRide.blend = 1; });   // tua tới điểm 5 (đỉnh), bỏ chặng bay vào cabin
      await frames(page, 4);
      out[`${view}|${night ? 'đêm' : 'ngày'}`] = await sample(page);
      if (view === 'swTour') { await page.keyboard.press('Escape'); await frames(page, 2); }   // thoát Tour: trả tốc độ quay, ngày/đêm, show như cũ
    }
  }
  await page.close();
  return { out, errors };
// Tiện ích chung cho các script kiểm tra: server tĩnh + mở trang bằng Chromium (Playwright).
import { fileURLToPath } from 'node:url';
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { chromium } from 'playwright';

const THREE_DIR = fileURLToPath(new URL('../node_modules/three/', import.meta.url));
const TYPES = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript', '.mjs': 'text/javascript', '.css': 'text/css', '.json': 'application/json', '.svg': 'image/svg+xml', '.mp3': 'audio/mpeg', '.png': 'image/png' };

/** Server tĩnh tối giản cho một thư mục (theo symlink). Trả về { url, close }. */
export function serveDir(dir) {
  const root = path.resolve(dir);
  const server = http.createServer((req, res) => {
    let p = decodeURIComponent(new URL(req.url, 'http://x').pathname);
    if (p.endsWith('/')) p += 'index.html';
    let file = path.join(root, p);
    if (!file.startsWith(root)) { res.writeHead(403); return res.end(); }
    // Bản gốc nạp three từ /three/… : nếu thư mục không có thì lấy từ node_modules/three của project
    if (p.startsWith('/three/') && !fs.existsSync(file)) file = path.join(THREE_DIR, p.slice('/three/'.length));
    fs.readFile(file, (err, data) => {
      if (err) { res.writeHead(404); return res.end('not found'); }
      res.writeHead(200, { 'content-type': TYPES[path.extname(file)] || 'application/octet-stream' });
      res.end(data);
    });
  });
  return new Promise((ok) => server.listen(0, '127.0.0.1', () => ok({ url: `http://127.0.0.1:${server.address().port}/`, close: () => server.close() })));
}

export async function launch() {
  return chromium.launch({
    executablePath: process.env.CHROMIUM_PATH || undefined,
    args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist']
  });
}

/** Mở trang với ?test, chặn font Google (không cần cho kiểm tra), chờ khung hình đầu.
    before(page): chạy trước khi mở trang (gắn route / lắng nghe yêu cầu, console từ lúc đầu). */
export async function openApp(browser, url, { width = 480, height = 270, mobile = false, before = null } = {}) {
  const page = await browser.newPage(mobile ? { viewport: { width, height }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 } : { viewport: { width, height } });
  const errors = []; page.setDefaultTimeout(240000);
  if (before) await before(page);
  page.on('pageerror', (e) => errors.push(String(e)));
  page.on('console', (m) => { if (m.type() === 'error' && !/fonts\.(googleapis|gstatic)|ERR_FAILED|net::/.test(m.text())) errors.push(m.text()); });
  await page.route(/fonts\.(googleapis|gstatic)\.com/, (r) => r.abort());
  await page.goto(url + (url.includes('?') ? '&' : '?') + 'test', { waitUntil: 'load', timeout: 180000 });
  await page.waitForFunction(() => window.__app && document.getElementById('loading')?.classList.contains('done'), null, { timeout: 180000 });
  return { page, errors };
}

/** Chờ n khung hình. */
export const frames = (page, n = 2) => page.evaluate((n) => new Promise((ok) => { let i = 0; const f = () => (++i >= n ? ok() : requestAnimationFrame(f)); requestAnimationFrame(f); }), n);

/** Chờ hiệu ứng bay camera (flyTo) kết thúc. */
// Phần mềm dựng hình (SwiftShader) rất chậm nên tua nhanh: đẩy tiến độ bay gần tới đích để khung hình kế tiếp hoàn tất.
export async function waitFlight(page) {
  await page.evaluate(() => { const f = window.__app.cam.flight; if (window.__app.cam.mode === 'fly') f.t = Math.max(f.t, 0.999); });
  await page.waitForFunction(() => window.__app.cam.mode !== 'fly', null, { timeout: 240000 });
}

/** Bấm một phần tử: ở chế độ gọn thì mở đúng tờ chứa nó trước (reveal), chờ 1 khung, rồi bấm. */
export async function tap(page, sel) {
  await page.evaluate((s) => window.__app.ui?.reveal(document.querySelector(s)), sel);
  await frames(page, 1);
  await page.click(sel);
}

/** Như tap nhưng cho ô chọn (select). */
export async function pick(page, sel, value) {
  await page.evaluate((s) => window.__app.ui?.reveal(document.querySelector(s)), sel);
  await frames(page, 1);
  await page.selectOption(sel, value);
}

/** Chọn cầu rồi bấm nút góc nhìn. */
export async function pickView(page, bridge, view) {
  await tap(page, `button[data-bridge="${bridge}"]`);
  await waitFlight(page);
  await tap(page, `button[data-view="${view}"]`);
  await waitFlight(page);
}

